begin;
create extension if not exists pgtap with schema extensions;
set search_path=public,extensions;select plan(27);
select ok((select bool_and(rowsecurity) from pg_tables where schemaname='public' and tablename in ('study_groups','group_teacher_assignments','student_enrollments','lms_commands','lms_events')),'Delivery tables enforce RLS');
select ok(not has_table_privilege('authenticated','public.student_enrollments','select'),'Raw enrollment prices/contact identifiers are not exposed');
select ok(not has_table_privilege('authenticated','public.lms_commands','select'),'Request receipts remain private');
select ok(not has_table_privilege('authenticated','public.study_groups','insert'),'Group writes require checked commands');
create temporary table lms_scope(label text primary key,id uuid);grant select,insert on lms_scope to authenticated;
insert into auth.users(id,email,email_confirmed_at) values('99999600-0000-0000-0000-000000000001','native-group-owner@example.test',now()),('99999600-0000-0000-0000-000000000002','native-group-teacher@example.test',now()),('99999600-0000-0000-0000-000000000003','native-group-other@example.test',now());
set local role authenticated;set local request.jwt.claim.sub='99999600-0000-0000-0000-000000000001';
insert into lms_scope select 'tenant',public.create_business('Native group learning');
insert into lms_scope select 'branch',id from public.branches where tenant_id=(select id from lms_scope where label='tenant') limit 1;
insert into lms_scope select 'course',public.save_course((select id from lms_scope where label='tenant'),null,gen_random_uuid(),0,'{"name":"Native English","standard_price":"750000.10","pricing_model":"monthly"}');
insert into lms_scope select 'student',public.save_student((select id from lms_scope where label='tenant'),gen_random_uuid(),null,'{"first_name":"Native enrolled student","phone":"998907771119"}','{}',array[(select id from lms_scope where label='branch')]);
insert into lms_scope select 'group',public.save_study_group((select id from lms_scope where label='tenant'),null,gen_random_uuid(),0,jsonb_build_object('branch_id',(select id from lms_scope where label='branch'),'course_id',(select id from lms_scope where label='course'),'name','Native Group','capacity','1','start_date',(now() at time zone 'Asia/Tashkent')::date::text));
insert into lms_scope select 'target',public.save_study_group((select id from lms_scope where label='tenant'),null,gen_random_uuid(),0,jsonb_build_object('branch_id',(select id from lms_scope where label='branch'),'course_id',(select id from lms_scope where label='course'),'name','Native Destination','capacity','1','start_date',(now() at time zone 'Asia/Tashkent')::date::text));
insert into lms_scope select 'enrollment',public.create_student_enrollment((select id from lms_scope where label='tenant'),(select id from lms_scope where label='group'),(select id from lms_scope where label='student'),'99999600-0000-0000-0000-000000000010',jsonb_build_object('enrollment_date',(now() at time zone 'Asia/Tashkent')::date::text,'effective_start_date',(now() at time zone 'Asia/Tashkent')::date::text,'agreed_price','9007199254740993.01','pricing_model','monthly','notes','Private administrator note'));
select is(public.student_enrollment_details((select id from lms_scope where label='tenant'),(select id from lms_scope where label='enrollment'))->'enrollment'->>'customer_id',(select id::text from lms_scope where label='student'),'Enrollment uses original student identity');
select is(public.student_enrollment_details((select id from lms_scope where label='tenant'),(select id from lms_scope where label='enrollment'))->'enrollment'->>'agreed_price','9007199254740993.01','Agreed price preserves exact decimal text');
select is(public.create_student_enrollment((select id from lms_scope where label='tenant'),(select id from lms_scope where label='group'),(select id from lms_scope where label='student'),'99999600-0000-0000-0000-000000000010',jsonb_build_object('enrollment_date',(now() at time zone 'Asia/Tashkent')::date::text,'effective_start_date',(now() at time zone 'Asia/Tashkent')::date::text,'agreed_price','9007199254740993.01','pricing_model','monthly','notes','Private administrator note')),(select id from lms_scope where label='enrollment'),'Exact retry returns original enrollment');
select is(public.study_group_details((select id from lms_scope where label='tenant'),(select id from lms_scope where label='group'))->'counts'->>'reserved_seats','1','Pending enrollment reserves capacity');
select throws_ok($$select public.create_student_enrollment((select id from lms_scope where label='tenant'),(select id from lms_scope where label='group'),(select id from lms_scope where label='student'),gen_random_uuid(),jsonb_build_object('enrollment_date',(now() at time zone 'Asia/Tashkent')::date::text,'effective_start_date',(now() at time zone 'Asia/Tashkent')::date::text,'agreed_price','1','pricing_model','monthly'))$$,'23505','Student already has an open enrollment in this group','Duplicate open enrollment denied');
select throws_ok($$select public.change_group_status((select id from lms_scope where label='tenant'),(select id from lms_scope where label='group'),gen_random_uuid(),1,'cancelled','Native cancellation')$$,'P0001','Close reserved enrollments before completing, cancelling or archiving the group','Group closing requires enrollment closure');
select throws_ok($$select public.update_student_enrollment((select id from lms_scope where label='tenant'),(select id from lms_scope where label='enrollment'),gen_random_uuid(),0,'{"status":"cancelled","reason":"Stale edit"}')$$,'40001','Enrollment changed; reload','Stale enrollment version denied');
insert into lms_scope select 'employee',public.save_employee((select id from lms_scope where label='tenant'),null,'Native teacher','','native-group-teacher@example.test','Teacher','active',(now() at time zone 'Asia/Tashkent')::date,'',array[(select id from lms_scope where label='branch')]);
create temporary table teacher_token(token text);grant select,insert on teacher_token to authenticated;
insert into teacher_token select public.create_employee_invitation((select id from lms_scope where label='tenant'),(select id from lms_scope where label='employee'),(select id from public.business_roles where tenant_id=(select id from lms_scope where label='tenant') and system_key='teacher'));
set local request.jwt.claim.sub='99999600-0000-0000-0000-000000000002';select public.accept_employee_invitation((select token from teacher_token));
set local request.jwt.claim.sub='99999600-0000-0000-0000-000000000001';
select public.set_group_teachers((select id from lms_scope where label='tenant'),(select id from lms_scope where label='group'),gen_random_uuid(),1,array[(select id from lms_scope where label='employee')],(select id from lms_scope where label='employee'),'Initial teacher');
set local request.jwt.claim.sub='99999600-0000-0000-0000-000000000002';
select is(public.group_directory((select id from lms_scope where label='tenant'))->>'total','1','Teacher sees assigned group only');
select throws_ok($$select public.study_group_details((select id from lms_scope where label='tenant'),(select id from lms_scope where label='target'))$$,'42501','Group access denied','Unassigned group ID denied');
select ok(not(public.student_enrollment_details((select id from lms_scope where label='tenant'),(select id from lms_scope where label='enrollment'))->'enrollment'?'agreed_price'),'Teacher detail omits agreed tuition');
select ok(not(public.student_enrollment_details((select id from lms_scope where label='tenant'),(select id from lms_scope where label='enrollment'))->'enrollment'?'notes'),'Teacher detail omits private administrator notes');
select is(public.enrollment_directory((select id from lms_scope where label='tenant'))->'rows'->0->>'agreed_price',null::text,'Teacher directory omits agreed tuition');
select throws_ok($$select public.lms_history((select id from lms_scope where label='tenant'),(select id from lms_scope where label='group'))$$,'42501','Academic history denied','Teacher cannot read administrative snapshots');
select throws_ok($$select public.financial_report((select id from lms_scope where label='tenant'),'payments')$$,'42501',null,'Academic permissions expose no financial reports');
set local request.jwt.claim.sub='99999600-0000-0000-0000-000000000001';
insert into lms_scope select 'moved',public.transfer_student_enrollment((select id from lms_scope where label='tenant'),(select id from lms_scope where label='enrollment'),(select id from lms_scope where label='target'),gen_random_uuid(),1,(now() at time zone 'Asia/Tashkent')::date::text,'{"agreed_price":"0.00","pricing_model":"per_lesson"}','Native transfer');
select is(public.student_enrollment_details((select id from lms_scope where label='tenant'),(select id from lms_scope where label='moved'))->'enrollment'->>'transferred_from_id',(select id::text from lms_scope where label='enrollment'),'Transfer retains source enrollment link');
select is(public.student_enrollment_details((select id from lms_scope where label='tenant'),(select id from lms_scope where label='enrollment'))->'enrollment'->>'agreed_price','9007199254740993.01','Transfer preserves original agreement');
select is((select count(*)::integer from public.customers where tenant_id=(select id from lms_scope where label='tenant')),1,'Transfer creates no duplicate person');
set constraints all immediate;set constraints all deferred;
set local request.jwt.claim.sub='99999600-0000-0000-0000-000000000003';
select throws_ok($$select public.study_group_details((select id from lms_scope where label='tenant'),(select id from lms_scope where label='group'))$$,'42501','Group access denied','Foreign membership cannot access group');
select is((select count(*)::integer from public.study_groups where tenant_id=(select id from lms_scope where label='tenant')),0,'Direct group metadata enforces RLS');
set local request.jwt.claim.sub='';
select throws_ok($$select public.student_enrollment_details((select id from lms_scope where label='tenant'),(select id from lms_scope where label='moved'))$$,'42501','Enrollment access denied','Subjectless enrollment denied');
reset role;
insert into public.customers(id,tenant_id,first_name,phone,status_id) select '99999600-0000-0000-0000-000000000020',(select id from lms_scope where label='tenant'),'Capacity guard student','998907771120',id from public.customer_statuses where tenant_id=(select id from lms_scope where label='tenant') and is_default limit 1;
insert into public.student_profiles(tenant_id,customer_id,student_identifier) values((select id from lms_scope where label='tenant'),'99999600-0000-0000-0000-000000000020','NATIVE-CAPACITY');
select throws_ok($$insert into public.student_enrollments(tenant_id,group_id,branch_id,customer_id,enrollment_date,effective_start_date,status,agreed_price,pricing_model,created_by) values((select id from lms_scope where label='tenant'),(select id from lms_scope where label='target'),(select id from lms_scope where label='branch'),'99999600-0000-0000-0000-000000000020',current_date,current_date,'pending',0,'monthly','99999600-0000-0000-0000-000000000001');set constraints all immediate$$,'23514','Group capacity exceeded','Deferred database capacity guard rejects privileged overbooking');
select is((select count(*)::integer from public.student_enrollments where tenant_id=(select id from lms_scope where label='tenant') and group_id=(select id from lms_scope where label='target')),1,'Failed overbooking rolls back entirely');
select is((select count(*)::integer from public.financial_transactions where tenant_id=(select id from lms_scope where label='tenant')),0,'Academic operations post no financial transactions');
select * from finish();rollback;
